const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

for (const lvlId of ['level_25', 'level_31', 'level_43', 'level_54']) {
  const lvlPath = resolve(__dirname, `../../data/levels/${lvlId}.json`);
  const levelJson: LevelJSON = JSON.parse(readFileSync(lvlPath, 'utf-8'));
  const seeds = getGoldenSeedIds(lvlId);

  console.log(`\n=== Testing ${lvlId} (${seeds.length} golden seeds) ===`);
  for (const d of [14, 18, 20, 22, 24, 26, 28]) {
    const m = runSimulationSync(levelJson, 100, d, 0, undefined, undefined, seeds);
    console.log(`Deck ${d} -> Pass Rate: ${m.passRate.toFixed(1)}%, CWR: ${m.closeWinRate.toFixed(1)}%`);
  }
}
"

