"  public async runFullLevelAnalysisAsync(
    levelJson: LevelJSON,
    options?: {
      onProgress?: (stageDesc: string, pct: number) => void;
      seedOffset?: number;
      botConfig?: Partial<BotConfig>;
    }
  ): Promise<LevelAnalysisReport> {
    const seedOffset = options?.seedOffset ?? 42;
    const onProgress = options?.onProgress;

    // Stage 1: Target 1 - Strict Brief (70% CWR) Calibration on Stochastic PRNG
    onProgress?.('Target 1: Calibrating 70% Close Win Deck Size (Stochastic PRNG)...', 10);
    const targetBrief = await this.calibrateAsync(
      levelJson,
      2000,
      70.0,
      2.0,
      seedOffset,
      options?.botConfig,
      (step) => {
        onProgress?.(`Target 1: Testing Deck ${step.deckSize} cards (CWR: ${step.metrics.closeWinRate.toFixed(1)}%)...`, 25);
      },
      undefined // Strictly stochastic random deals
    );

